import os, asyncio, pathlib, json
from playwright.async_api import async_playwright
import qa
ARGS = ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader']
OUT = pathlib.Path('/home/claude/qa/review/packet')
IDS = ['plate-carree', 'gall-peters', 'mercator', 'equal-earth', 'robinson', 'winkel-tripel', 'spilhaus', 'polar-equidistant', 'polar-equal-area']
shots, texts = [], []
def note(name, caption): shots.append((name, caption))
async def go(pg, id):
    await pg.evaluate(f"() => {{ const L = window.__lab; L.state.animate = false; L.goTo('{id}'); }}"); await pg.wait_for_timeout(700)
async def country(pg, iso, pos=None, proj=None):
    js = "() => { const L = window.__lab; L.state.animate = false; " + (f"L.goTo('{proj}'); " if proj else "") + f"L.chooseCountry(L.mainFeatureFor('{iso}')); " + (f"L.moveCountryTo({pos[0]}, {pos[1]}); " if pos else "") + "L.render(); }"
    await pg.evaluate(js); await pg.wait_for_timeout(900)
async def panel_text(pg, sel): return await pg.evaluate(f"() => document.querySelector('{sel}').innerText")
async def main():
    qa.APP = pathlib.Path('/home/claude/projection-lab-repo/index.html').read_text()
    async with async_playwright() as p:
        b = await p.chromium.launch(proxy={'server': os.environ['HTTPS_PROXY'], 'bypass': 'lab.test'}, args=ARGS)
        # ---------- Chromebook 1366x768 ----------
        ctx = await b.new_context(viewport={'width': 1366, 'height': 768}, locale='en-US'); await qa.setup(ctx); pg = await ctx.new_page()
        await pg.goto('https://lab.test/index.html'); await pg.wait_for_timeout(700)
        await pg.screenshot(path=str(OUT/'c01-loading.png')); note('c01-loading.png', 'Chromebook 1366×768: the loading screen, about a second after opening the link')
        await pg.wait_for_function('window.__lab && window.__lab.state.ready', timeout=120000); await pg.wait_for_timeout(1500)
        await pg.screenshot(path=str(OUT/'c02-first-view.png')); note('c02-first-view.png', 'Chromebook: what you see when the app has loaded (it opens on Mercator, Projection tab)')
        texts.append(('Whole page text when it has loaded (Chromebook)', await pg.evaluate("() => document.body.innerText")))
        for k, id in enumerate(IDS):
            await go(pg, id)
            await pg.evaluate("() => { document.querySelectorAll('#panel-proj details').forEach(d => d.open = false); document.querySelector('.panels').scrollTop = 0; }"); await pg.wait_for_timeout(200)
            name = f'c{3 + k:02d}-proj-{id}.png'
            await pg.screenshot(path=str(OUT/name)); note(name, f'Chromebook: Projection tab on map {k + 1} of 9 (key {k + 1})')
            await pg.evaluate("() => document.querySelectorAll('#panel-proj details').forEach(d => d.open = true)")
            texts.append((f'Projection tab text, map {k + 1} ({id}), with "What do these words mean?" and "More about" both opened', await panel_text(pg, '#panel-proj')))
        await go(pg, 'mercator')
        await pg.evaluate("() => { const d = document.querySelector('#panel-proj details.glossary'); d.open = true; document.querySelector('#panel-proj details.more').open = false; document.querySelector('.panels').scrollTop = 0; }"); await pg.wait_for_timeout(300)
        await pg.screenshot(path=str(OUT/'c12-glossary-open.png')); note('c12-glossary-open.png', 'Chromebook: Mercator with "What do these words mean?" opened')
        await pg.evaluate("() => { document.querySelector('#panel-proj details.glossary').open = false; const m = document.querySelector('#panel-proj details.more'); m.open = true; m.scrollIntoView({block: 'nearest'}); }"); await pg.wait_for_timeout(400)
        await pg.screenshot(path=str(OUT/'c13-more-open.png')); note('c13-more-open.png', 'Chromebook: Mercator with "More about Mercator" opened (panel scrolled to it)')
        await pg.evaluate("() => { document.querySelectorAll('#panel-proj details').forEach(d => d.open = false); document.querySelector('.panels').scrollTop = 0; }")
        await pg.evaluate("() => { const L = window.__lab; L.state.animate = true; L.goTo('equal-earth'); L.state.morph.dur = 1e9; L.state.morph.t0 = performance.now() - 0.5e9; L.render(); }"); await pg.wait_for_timeout(500)
        await pg.screenshot(path=str(OUT/'c14-mid-morph.png')); note('c14-mid-morph.png', 'Chromebook: halfway through the 2-second animation from Mercator to Equal Earth (pressing 4)')
        await pg.evaluate("() => { const L = window.__lab; L.state.morph.dur = 1; }"); await pg.wait_for_timeout(600)
        await go(pg, 'mercator')
        await pg.click('#togImagery'); await pg.wait_for_timeout(500)
        await pg.screenshot(path=str(OUT/'c15-imagery-off.png')); note('c15-imagery-off.png', 'Chromebook: Mercator with the satellite picture switched off (second round button under the map)')
        await pg.click('#togImagery'); await pg.click('#togCircles'); await pg.click('#togGrid'); await pg.wait_for_timeout(500)
        await pg.screenshot(path=str(OUT/'c16-circles-grid-off.png')); note('c16-circles-grid-off.png', 'Chromebook: Mercator with the same-size circles and the grid lines switched off')
        await pg.click('#togCircles'); await pg.click('#togGrid'); await pg.wait_for_timeout(300)
        await pg.evaluate("() => { const L = window.__lab, p = L.PROJ.mercator; const xy = L.lonLatToScreen(10, 50); L.setZoomKeepingPoint(4, (xy[0] - L.getVT().kx) / L.getVT().z, (xy[1] - L.getVT().ky) / L.getVT().z, xy[0], xy[1]); L.render(); }"); await pg.wait_for_timeout(1500)
        await pg.screenshot(path=str(OUT/'c17-zoomed.png')); note('c17-zoomed.png', 'Chromebook: Mercator zoomed in 4× on Europe (+ button, mouse wheel or pinch)')
        await pg.evaluate("() => { window.__lab.zoomFit(); }"); await pg.wait_for_timeout(1200)
        # Measure
        await pg.click('#tab-measure'); await pg.wait_for_timeout(400)
        await pg.screenshot(path=str(OUT/'c18-measure-default.png')); note('c18-measure-default.png', 'Chromebook: Measure tab as it first opens (Mercator)')
        texts.append(('Measure tab text, as it first opens (Mercator)', await panel_text(pg, '#panel-measure')))
        await pg.evaluate("() => window.__lab.setProbe(20, 70)"); await pg.wait_for_timeout(500)
        await pg.screenshot(path=str(OUT/'c19-measure-70N.png')); note('c19-measure-70N.png', 'Chromebook: Measure tab after dragging the white circle to northern Scandinavia (70°N) on Mercator')
        texts.append(('Measure tab text, circle at 70°N 20°E on Mercator', await panel_text(pg, '#panel-measure')))
        await go(pg, 'equal-earth'); await pg.evaluate("() => window.__lab.setProbe(20, 70)"); await pg.wait_for_timeout(400)
        await pg.screenshot(path=str(OUT/'c20-measure-equal-earth.png')); note('c20-measure-equal-earth.png', 'Chromebook: same circle position after switching to Equal Earth')
        texts.append(('Measure tab text, circle at 70°N 20°E on Equal Earth', await panel_text(pg, '#panel-measure')))
        await go(pg, 'spilhaus'); await pg.evaluate("() => window.__lab.setProbe(130, 40)"); await pg.wait_for_timeout(500)
        await pg.screenshot(path=str(OUT/'c21-measure-spilhaus.png')); note('c21-measure-spilhaus.png', 'Chromebook: Measure tab on Spilhaus with the circle dragged toward a corner (near Korea/Japan)')
        texts.append(('Measure tab text, circle near Korea on Spilhaus', await panel_text(pg, '#panel-measure')))
        await pg.click('#uKm'); await pg.wait_for_timeout(300)
        texts.append(('Measure tab text after pressing Kilometers', await panel_text(pg, '#panel-measure')))
        await pg.click('#uMi'); await pg.wait_for_timeout(200)
        # Country
        await go(pg, 'mercator')
        await pg.click('#tab-country'); await pg.wait_for_timeout(900)
        await pg.screenshot(path=str(OUT/'c22-country-default.png')); note('c22-country-default.png', 'Chromebook: Country tab as it first opens on a US computer (it starts with the United States)')
        texts.append(('Country tab text, as it first opens (United States, Mercator)', await panel_text(pg, '#panel-country')))
        texts.append(('Label drawn on the map next to the chosen country', await pg.evaluate("() => window.__lab.CM.name + ' / ' + window.__lab.CM.tag")))
        await country(pg, 'GL')
        await pg.screenshot(path=str(OUT/'c23-country-greenland.png')); note('c23-country-greenland.png', 'Chromebook: Country tab after tapping Greenland on the map (Mercator)')
        texts.append(('Country tab text, Greenland chosen, in its real place (Mercator)', await panel_text(pg, '#panel-country')))
        await pg.click('.c-moves .pair-btn[data-move="eq"]'); await pg.wait_for_timeout(1400)
        await pg.screenshot(path=str(OUT/'c24-country-greenland-equator.png')); note('c24-country-greenland-equator.png', 'Chromebook: after pressing "Equator" (Greenland moved to the Equator, Mercator)')
        texts.append(('Country tab text, Greenland moved to the Equator (Mercator)', await panel_text(pg, '#panel-country')))
        await go(pg, 'equal-earth')
        await pg.screenshot(path=str(OUT/'c25-country-greenland-equal-earth.png')); note('c25-country-greenland-equal-earth.png', 'Chromebook: same, after switching to Equal Earth')
        texts.append(('Country tab text, Greenland at the Equator (Equal Earth)', await panel_text(pg, '#panel-country')))
        await country(pg, 'US', None, 'spilhaus')
        await pg.screenshot(path=str(OUT/'c26-country-us-spilhaus.png')); note('c26-country-us-spilhaus.png', 'Chromebook: Country tab, United States in its real place on Spilhaus')
        texts.append(('Country tab text, United States in its real place (Spilhaus)', await panel_text(pg, '#panel-country')))
        await country(pg, 'BR', (-50, 60), 'polar-equidistant')
        await pg.screenshot(path=str(OUT/'c27-country-brazil-polar.png')); note('c27-country-brazil-polar.png', 'Chromebook: Brazil dragged to 60°N on Polar Equidistant')
        texts.append(('Country tab text, Brazil dragged to 60°N (Polar Equidistant)', await panel_text(pg, '#panel-country')))
        # About
        await pg.click('#aboutBtn'); await pg.wait_for_timeout(500)
        await pg.screenshot(path=str(OUT/'c28-about-top.png')); note('c28-about-top.png', 'Chromebook: About button, top of the dialog')
        await pg.evaluate("() => { const d = document.getElementById('about'); d.scrollTop = d.scrollHeight / 2; }"); await pg.wait_for_timeout(300)
        await pg.screenshot(path=str(OUT/'c29-about-middle.png')); note('c29-about-middle.png', 'Chromebook: About dialog, scrolled half way')
        await pg.evaluate("() => { const d = document.getElementById('about'); d.scrollTop = d.scrollHeight; }"); await pg.wait_for_timeout(300)
        await pg.screenshot(path=str(OUT/'c30-about-bottom.png')); note('c30-about-bottom.png', 'Chromebook: About dialog, bottom')
        texts.append(('About dialog, full text', await pg.evaluate("() => document.getElementById('about').innerText")))
        await pg.keyboard.press('Escape')
        labels = await pg.evaluate("""() => [...document.querySelectorAll('button, select, [role=tab]')].filter(e => e.offsetParent).map(e => `${(e.innerText || '').trim().replace(/\\s+/g, ' ') || '(no visible text)'}  | spoken name: ${e.getAttribute('aria-label') || (e.innerText || '').trim().replace(/\\s+/g, ' ')}${e.title ? '  | hover text: ' + e.title : ''}`)""")
        texts.append(('Every button and control on screen: visible text | name a screen reader speaks | hover text', '\n'.join(labels)))
        texts.append(('What the map itself announces to a screen reader (Country tab, Brazil)', await pg.evaluate("() => document.getElementById('map').getAttribute('aria-label')")))
        await ctx.close()
        # ---------- Projector 1280x720 ----------
        ctx = await b.new_context(viewport={'width': 1280, 'height': 720}, locale='en-US'); await qa.setup(ctx); pg = await ctx.new_page()
        await pg.goto('https://lab.test/index.html'); await pg.wait_for_function('window.__lab && window.__lab.state.ready', timeout=120000); await pg.wait_for_timeout(1500)
        await pg.screenshot(path=str(OUT/'p01-projector-first-view.png')); note('p01-projector-first-view.png', 'Projector at 1280×720: first view')
        await pg.click('#tab-country'); await pg.wait_for_timeout(500); await country(pg, 'GL', (-40, 0))
        await pg.screenshot(path=str(OUT/'p02-projector-country.png')); note('p02-projector-country.png', 'Projector 1280×720: Country tab, Greenland at the Equator on Mercator')
        await pg.click('#tab-measure'); await pg.wait_for_timeout(500)
        await pg.screenshot(path=str(OUT/'p03-projector-measure.png')); note('p03-projector-measure.png', 'Projector 1280×720: Measure tab')
        await ctx.close()
        # ---------- Phone 390x844 ----------
        ctx = await b.new_context(viewport={'width': 390, 'height': 844}, device_scale_factor=2, is_mobile=True, has_touch=True, locale='en-US'); await qa.setup(ctx); pg = await ctx.new_page()
        await pg.goto('https://lab.test/index.html'); await pg.wait_for_function('window.__lab && window.__lab.state.ready', timeout=120000); await pg.wait_for_timeout(1500)
        await pg.screenshot(path=str(OUT/'m01-phone-first-view.png')); note('m01-phone-first-view.png', 'Phone 390×844: first screen without scrolling')
        await pg.screenshot(path=str(OUT/'m02-phone-full-page.png'), full_page=True); note('m02-phone-full-page.png', 'Phone: the whole page, scrolled top to bottom (Projection tab)')
        await pg.click('#tab-country'); await pg.wait_for_timeout(900)
        await pg.screenshot(path=str(OUT/'m03-phone-country.png'), full_page=True); note('m03-phone-country.png', 'Phone: whole page with the Country tab open')
        await pg.click('#tab-measure'); await pg.wait_for_timeout(500)
        await pg.screenshot(path=str(OUT/'m04-phone-measure.png'), full_page=True); note('m04-phone-measure.png', 'Phone: whole page with the Measure tab open')
        await ctx.close()
        await b.close()
    json.dump({'shots': shots, 'texts': texts}, open(OUT/'packet.json', 'w'))
asyncio.run(main())
